    private func checklistItems(_ id: String) throws -> [[String: Any]] {
        let encoded = try XCTUnwrap(storedTask(id)["checklist"] as? String)
        return try XCTUnwrap(JSONSerialization.jsonObject(with: Data(encoded.utf8)) as? [[String: Any]])
    }

    private func checklistSaveRequest(_ id: String, opening: [String: Any], checklist: [[String: Any]], patch: [String: Any]) throws -> [String: Any] {
        let draft = try XCTUnwrap(opening["draft"] as? [String: Any])
        let base = Dictionary(uniqueKeysWithValues: patch.keys.map { ($0, draft[$0] ?? NSNull()) })
        return ["id": id, "requestId": UUID().uuidString.lowercased(), "base": base, "patch": patch,
                "scheduleBase": try XCTUnwrap(opening["scheduleBase"]),
                "checklist": ["base": try checklistItems(id), "value": checklist]]
    }

    func testEditorBackdateDraftCommitFailureColdReplayAndCorrection() async throws {
        let id = try await seedDestinationTask()
        let sqlite = try SQLiteBridge(url: database)
        _ = try sqlite.execute("UPDATE tasks SET recurrence = ?, timeSpentMinutes = 17 WHERE id = ?",
                               parametersJSON: json([json(["rule": "daily", "strategy": "strict", "count": 3, "seriesId": id]), id]))
        func comparable(_ row: [String: Any], excluding fields: Set<String> = []) throws -> String {
            try datePreservedFields(object(recurrenceComparableRow(row)), excluding: fields)
        }
        func snapshot() throws -> [String] {
            var tables = try nineTableSnapshot(sqlite)
            let rows = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(tables[0].utf8)) as? [[String: Any]])
            // Activation may reorder JSON object keys; preserve every value and array position.
            tables[0] = try json(rows.map { try object(comparable($0)) })
            return tables
        }
        let faults = HostIOFaults()
        let core = host(faults, bundleURL: try dateBundle(at: "2036-10-04T12:00:00.000Z"))
        _ = try await core.start()
        _ = try await core.call("captureSubmit", argumentsJSON: capture(core, title: "Backdate sibling", id: UUID().uuidString.lowercased()))
        let opening = try object(await core.call("editorModel", argumentsJSON: json([id])))
        let before = try snapshot()
        let original = try storedTask(id)
        let count = try taskCount()
        let completion = "2036-10-02T18:23:45.678Z"
        let edited = try object(await core.call("editDraft", argumentsJSON: json([json([
            "id": id, "draft": try XCTUnwrap(opening["draft"]),
            "edit": ["type": "backdatedCompletion", "completedAt": completion, "timeSpentText": "4.2 minutes"],
        ])])))
        let draft = try XCTUnwrap(edited["draft"] as? [String: Any])
        XCTAssertEqual(draft["status"] as? String, "done")
        XCTAssertEqual(draft["completedAt"] as? String, completion)
        XCTAssertEqual(draft["timeSpentMinutes"] as? Int, 42)
        XCTAssertEqual(try snapshot(), before, "Picker confirmation edits only the draft")
        let request = try checklistSaveRequest(id, opening: opening, checklist: checklistItems(id),
                                              patch: ["status": "done", "completedAt": completion, "timeSpentMinutes": 42])
        faults.beforeSQL = { if $0 == "COMMIT" { throw HostFailure("Injected backdate COMMIT failure") } }
        await expectFailure("SAVE_FAILED") { _ = try await core.call("checklistSave", argumentsJSON: json([json(request)])) }
        let pending = try Data(contentsOf: journal)
        await expectFailure("SAVE_FAILED") { _ = try await core.retryPending() }
        try assertJournalContentUnchanged(pending)
        XCTAssertEqual(try snapshot(), before)
        await core.close()
        let replay = host(bundleURL: try dateBundle(at: "2036-10-04T13:00:00.000Z", suffix:
            "MindwtrHost.checklistSavePrepare = function () { throw new Error('Backdate replay must not prepare'); };"))
        _ = try await replay.start()
        let saved = try storedTask(id)
        XCTAssertEqual(saved["completedAt"] as? String, completion)
        XCTAssertEqual(saved["timeSpentMinutes"] as? Int, 42)
        XCTAssertEqual(saved["rev"] as? Int, (original["rev"] as? Int ?? 0) + 1)
        XCTAssertEqual(try taskCount(), count + 1)
        let changed: Set<String> = ["status", "completedAt", "timeSpentMinutes", "isFocusedToday", "focusOrder", "recurrence", "rev", "revBy", "updatedAt"]
        XCTAssertEqual(try datePreservedFields(saved, excluding: changed), try datePreservedFields(original, excluding: changed))
        let after = try snapshot()
        XCTAssertEqual(Array(after.dropFirst()), Array(before.dropFirst()))
        let oldTasks = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(before[0].utf8)) as? [[String: Any]])
        let newTasks = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(after[0].utf8)) as? [[String: Any]])
        let siblingIDs = Set(oldTasks.compactMap { $0["id"] as? String }.filter { $0 != id })
        XCTAssertEqual(try json(oldTasks.filter { siblingIDs.contains($0["id"] as? String ?? "") }),
                       try json(newTasks.filter { siblingIDs.contains($0["id"] as? String ?? "") }))
        XCTAssertFalse(FileManager.default.fileExists(atPath: journal.path))
        await replay.close()
        let cold = host(bundleURL: try dateBundle(at: "2036-10-04T14:00:00.000Z")); _ = try await cold.start()
        XCTAssertEqual(try snapshot(), after)
        let reopened = try object(await cold.call("editorModel", argumentsJSON: json([id])))
        let correctedAt = "2036-10-01T17:02:03.456Z"
        let corrected = try object(await cold.call("editDraft", argumentsJSON: json([json([
            "id": id, "draft": try XCTUnwrap(reopened["draft"]),
            "edit": ["type": "backdatedCompletion", "completedAt": correctedAt],
        ])])))
        XCTAssertEqual((corrected["draft"] as? [String: Any])?["timeSpentMinutes"] as? Int, 42)
        let correction = try checklistSaveRequest(id, opening: reopened, checklist: checklistItems(id), patch: ["completedAt": correctedAt])
        _ = try await cold.call("checklistSave", argumentsJSON: json([json(correction)]))
        XCTAssertEqual(try storedTask(id)["completedAt"] as? String, correctedAt)
        XCTAssertEqual(try storedTask(id)["timeSpentMinutes"] as? Int, 42)
        XCTAssertEqual(try taskCount(), count + 1, "Correcting an already Done task creates no second recurrence child")
        let final = try snapshot()
        XCTAssertEqual(Array(final.dropFirst()), Array(after.dropFirst()))
        let finalTasks = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(final[0].utf8)) as? [[String: Any]])
        XCTAssertEqual(try json(newTasks.filter { $0["id"] as? String != id }),
                       try json(finalTasks.filter { $0["id"] as? String != id }))
        XCTAssertEqual(try comparable(storedTask(id), excluding: ["completedAt", "rev", "revBy", "updatedAt"]),
                       try comparable(saved, excluding: ["completedAt", "rev", "revBy", "updatedAt"]))
        await cold.close()
        let finalHost = host(bundleURL: try dateBundle(at: "2036-10-04T15:00:00.000Z")); _ = try await finalHost.start()
        XCTAssertEqual(try snapshot(), final)
        XCTAssertFalse(FileManager.default.fileExists(atPath: journal.path))
        await finalHost.close(); sqlite.close()
    }

    func testEditorTimeSpentTransportRecoveryAndCombinedClear() async throws {
        let id = try await seedDestinationTask()
        let faults = HostIOFaults()
        let core = host(faults, bundleURL: try dateBundle(at: "2026-09-30T12:00:00.000Z"))
        _ = try await core.start()
        _ = try await core.call("captureSubmit", argumentsJSON: capture(core, title: "Minutes sibling", id: UUID().uuidString.lowercased()))
        let opening = try object(await core.call("editorModel", argumentsJSON: json([id])))
        let sqlite = try SQLiteBridge(url: database)
        let before = try nineTableSnapshot(sqlite)
        let original = try storedTask(id)
        var statements = 0
        var confirmations = 0
        faults.beforeSQL = { _ in statements += 1 }
        faults.commandDiagnostic = { if $0 == "taskEditorTimeSpentApplied" { confirmations += 1 } }
        for invalid: Any in [true, "25", -1, ["minutes": 25]] {
            await expectFailure("INVALID_INPUT") {
                _ = try await core.call("saveDraft", argumentsJSON: datePayload(id, editor: opening, patch: ["timeSpentMinutes": invalid]))
            }
            let request = try checklistSaveRequest(id, opening: opening, checklist: checklistItems(id), patch: ["timeSpentMinutes": invalid])
            await expectFailure("INVALID_INPUT") { _ = try await core.call("checklistSave", argumentsJSON: json([json(request)])) }
        }
        await expectFailure("INVALID_INPUT") {
            _ = try await core.call("saveDraft", argumentsJSON: json([json([
                "id": id, "base": ["timeSpentMinutes": NSNull()], "patch": ["timeSpentMinutes": 37],
            ])]))
        }
        XCTAssertEqual(statements, 0)
        XCTAssertFalse(FileManager.default.fileExists(atPath: journal.path))
        faults.beforeSQL = { if $0 == "COMMIT" { throw HostFailure("Injected minutes COMMIT failure") } }
        await expectFailure("SAVE_FAILED") {
            _ = try await core.call("saveDraft", argumentsJSON: datePayload(id, editor: opening, patch: ["timeSpentMinutes": 37]))
        }
        let pending = try Data(contentsOf: journal)
        await expectFailure("SAVE_FAILED") { _ = try await core.retryPending() }
        try assertJournalContentUnchanged(pending)
        XCTAssertEqual(try nineTableSnapshot(sqlite), before)
        XCTAssertEqual(confirmations, 0)
        await core.close()
        let replayFaults = HostIOFaults()
        replayFaults.commandDiagnostic = { if $0 == "taskEditorTimeSpentApplied" { confirmations += 1 } }
        let replay = host(replayFaults, bundleURL: try dateBundle(at: "2026-09-30T13:00:00.000Z", suffix:
            "MindwtrHost.draftPrepare = function () { throw new Error('Minutes replay must not prepare'); };"))
        _ = try await replay.start()
        let saved = try storedTask(id)
        XCTAssertEqual(saved["timeSpentMinutes"] as? Int, 37)
        XCTAssertEqual(saved["rev"] as? Int, (original["rev"] as? Int ?? 0) + 1)
        let changed: Set<String> = ["timeSpentMinutes", "rev", "revBy", "updatedAt"]
        XCTAssertEqual(try datePreservedFields(saved, excluding: changed), try datePreservedFields(original, excluding: changed))
        let after = try nineTableSnapshot(sqlite)
        XCTAssertEqual(Array(after.dropFirst()), Array(before.dropFirst()))
        let oldTasks = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(before[0].utf8)) as? [[String: Any]])
        let newTasks = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(after[0].utf8)) as? [[String: Any]])
        XCTAssertEqual(try json(oldTasks.filter { $0["id"] as? String != id }), try json(newTasks.filter { $0["id"] as? String != id }))
        XCTAssertEqual(confirmations, 1)
        XCTAssertFalse(FileManager.default.fileExists(atPath: journal.path))
        let edited = try object(await replay.call("editorModel", argumentsJSON: json([id])))
        let clear = try checklistSaveRequest(id, opening: edited, checklist: checklistItems(id), patch: ["timeSpentMinutes": NSNull(), "status": "waiting"])
        _ = try await replay.call("checklistSave", argumentsJSON: json([json(clear)]))
        let cleared = try storedTask(id)
        XCTAssertTrue(cleared["timeSpentMinutes"] is NSNull)
        XCTAssertEqual(cleared["status"] as? String, "waiting")
        XCTAssertEqual(cleared["rev"] as? Int, (saved["rev"] as? Int ?? 0) + 1)
        XCTAssertEqual(try datePreservedFields(cleared, excluding: changed.union(["status", "focusOrder", "isFocusedToday"])),
                       try datePreservedFields(saved, excluding: changed.union(["status", "focusOrder", "isFocusedToday"])))
        XCTAssertEqual(confirmations, 2)
        let final = try nineTableSnapshot(sqlite)
        await replay.close()
        let cold = host(bundleURL: try dateBundle(at: "2026-09-30T14:00:00.000Z")); _ = try await cold.start()
        XCTAssertEqual(try nineTableSnapshot(sqlite), final)
        XCTAssertFalse(FileManager.default.fileExists(atPath: journal.path))
        await cold.close(); sqlite.close()
    }

    func testEditorStatusSameFinalStatusCascadesRetryAndColdReplay() async throws {
        for status in ["next", "done"] {
            let id = try await seedDestinationTask()
            let sqlite = try SQLiteBridge(url: database)
            _ = try sqlite.execute("UPDATE tasks SET status = ?, isFocusedToday = ?, completedAt = ?, timeSpentMinutes = 17 WHERE id = ?",
                                   parametersJSON: json([status, status == "next" ? 1 : 0,
                                                         status == "done" ? "2026-09-29T12:00:00.000Z" as Any : NSNull(), id]))
            let faults = HostIOFaults()
            let core = host(faults, bundleURL: try dateBundle(at: "2026-09-30T12:00:00.000Z"))
            _ = try await core.start()
            // Seed through the ordinary writer so load-time legacy fixture defaults
            // are already persisted before the preservation baseline is taken.
            _ = try await core.call("captureSubmit", argumentsJSON: capture(core, title: "Status sibling", id: UUID().uuidString.lowercased()))
            let opening = try object(await core.call("editorModel", argumentsJSON: json([id])))
            var edited = opening
            for selected in [status == "next" ? "reference" : "next", status] {
                edited = try object(await core.call("editDraft", argumentsJSON: json([json([
                    "id": id, "draft": try XCTUnwrap(edited["draft"]),
                    "edit": ["type": "fields", "patch": ["status": selected]],
                ])])))
            }
            let draft = try XCTUnwrap(edited["draft"] as? [String: Any])
            XCTAssertEqual(draft["status"] as? String, status)
            let field = status == "next" ? "focusedToday" : "completedAt"
            let request = try checklistSaveRequest(id, opening: opening, checklist: checklistItems(id),
                                                  patch: [field: try XCTUnwrap(draft[field])])
            let before = try nineTableSnapshot(sqlite)
            let original = try storedTask(id)
            var confirmations = 0
            faults.commandDiagnostic = { if $0 == "taskEditorStatusApplied" { confirmations += 1 } }
            faults.beforeSQL = { if $0 == "COMMIT" { throw HostFailure("Injected status COMMIT failure") } }
            await expectFailure("SAVE_FAILED") { _ = try await core.call("checklistSave", argumentsJSON: json([json(request)])) }
            let pending = try Data(contentsOf: journal)
            await expectFailure("SAVE_FAILED") { _ = try await core.retryPending() }
            try assertJournalContentUnchanged(pending)
            XCTAssertEqual(try nineTableSnapshot(sqlite), before)
            XCTAssertEqual(confirmations, 0)
            await core.close()
            let replayFaults = HostIOFaults()
            replayFaults.commandDiagnostic = { if $0 == "taskEditorStatusApplied" { confirmations += 1 } }
            let reopened = host(replayFaults, bundleURL: try dateBundle(at: "2026-09-30T13:00:00.000Z", suffix: """
            MindwtrHost.checklistSavePrepare = function () { throw new Error('Replay must not prepare status'); };
            """))
            _ = try await reopened.start()
            let saved = try storedTask(id)
            XCTAssertEqual(saved["status"] as? String, status)
            XCTAssertEqual(saved["timeSpentMinutes"] as? Int, 17)
            if status == "next" { XCTAssertEqual(saved["isFocusedToday"] as? Int, 0) }
            else { XCTAssertEqual(saved["completedAt"] as? String, saved["updatedAt"] as? String) }
            XCTAssertEqual(saved["rev"] as? Int, (original["rev"] as? Int ?? 0) + 1)
            let changed: Set<String> = ["isFocusedToday", "focusOrder", "completedAt", "rev", "revBy", "updatedAt"]
            XCTAssertEqual(try datePreservedFields(saved, excluding: changed), try datePreservedFields(original, excluding: changed))
            let after = try nineTableSnapshot(sqlite)
            XCTAssertEqual(Array(after.dropFirst()), Array(before.dropFirst()))
            let oldTasks = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(before[0].utf8)) as? [[String: Any]])
            let newTasks = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(after[0].utf8)) as? [[String: Any]])
            XCTAssertEqual(try json(oldTasks.filter { $0["id"] as? String != id }),
                           try json(newTasks.filter { $0["id"] as? String != id }))
            XCTAssertEqual(confirmations, 1)
            XCTAssertFalse(FileManager.default.fileExists(atPath: journal.path))
            let retried = try await reopened.retryPending(); XCTAssertNil(retried)
            await reopened.close()
            let cold = host(bundleURL: try dateBundle(at: "2026-09-30T14:00:00.000Z")); _ = try await cold.start()
            XCTAssertEqual(try nineTableSnapshot(sqlite), after)
            await cold.close(); sqlite.close()
        }
    }

