        faults.beforeSQL = { sql in
            if sql.range(of: #"(?i)^\s*(?:INSERT(?: OR \w+)? INTO|UPDATE|DELETE FROM)\s+projects\b"#, options: .regularExpression) != nil { writes += 1 }
        }
        for name in cases {
