        }
        faults.journalWrite = { journals += 1 }
        await expectFailure("STALE_REVISION") {
            _ = try await core.call("projectNotesWrite", argumentsJSON: json([json(request)]))
        }
        XCTAssertEqual(writes, 0); XCTAssertEqual(journals, 0)
        await core.close()
    }

