        for (index, id) in ids.enumerated() {
            let row = try storedTask(id)
            var tags = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(XCTUnwrap(row["tags"] as? String).utf8)) as? [String])
            tags.append("#retain184")
