        XCTAssertFalse((afterDelete["items"] as? [[String: Any]] ?? []).contains { ($0["row"] as? [String: Any])?["id"] as? String == id })
        let undo: [String: Any] = ["requestId": UUID().uuidString.lowercased(), "deleteRequestId": try XCTUnwrap(request["requestId"])]
