                } else {
                    var effect = try XCTUnwrap(checklist["effect"] as? [String: Any]), guards = try XCTUnwrap(effect["guards"] as? [String: Any])
                    guards["focusCount"] = 999; effect["guards"] = guards; checklist["effect"] = effect
