        let variants: [(String, [String: Any])] = [("wrong source", ["source": "done"]), ("extra field", ["status": "done"]),
            ("oversized instant", ["completedAt": String(repeating: "x", count: 201)]), ("oversized minutes", ["timeSpentText": String(repeating: "1", count: 201)]),
